static __declspec(noinline) int __fastcall _bisect_forward_serialno(OggVorbis_File* vf, ogg_int64_t begin,
                                                                   ogg_int64_t searched, ogg_int64_t end,
                                                                   long currentno, long m)   // 0x00C89E80 (static)
{
