    if (offsettest != -1) vf->seekable = 1;

    vf->links = 1;
    vf->vi = (vorbis_info*)calloc(vf->links, sizeof(*vf->vi));
    vf->vc = (vorbis_comment*)calloc(vf->links, sizeof(*vf->vc));
    ogg_stream_init(&vf->os, -1);

